<template>
  <el-card class="dashboard-card" shadow="hover">
    <template #header>
      <div class="card-header">
        <span>{{ t('dashboard.recentEvents.title') }}</span>
        <el-button text size="small" @click="$emit('refresh')">{{ t('dashboard.recentEvents.refresh') }}</el-button>
      </div>
    </template>

    <el-table :data="events" v-if="events.length" size="small">
      <el-table-column prop="title" :label="t('dashboard.recentEvents.eventColumn')" show-overflow-tooltip />
      <el-table-column prop="status" :label="t('dashboard.recentEvents.statusColumn')" width="90">
        <template #default="{ row }">
          <el-tag :type="statusType(row.status)" size="small">{{ row.status }}</el-tag>
        </template>
      </el-table-column>
      <el-table-column prop="severity" :label="t('dashboard.recentEvents.severityColumn')" width="90">
        <template #default="{ row }">
          <el-tag :type="severityType(row.severity)" size="small">{{ row.severity }}</el-tag>
        </template>
      </el-table-column>
      <el-table-column prop="timestamp" :label="t('dashboard.recentEvents.timeColumn')" width="160">
        <template #default="{ row }">
          {{ formatTime(row.timestamp) }}
        </template>
      </el-table-column>
    </el-table>

    <div v-else class="empty-placeholder">{{ t('dashboard.recentEvents.empty') }}</div>
  </el-card>
</template>

<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import { useLocale } from '@/composables/useLocale'
import type { RecentEvent } from '@/api/dashboard'

interface Props {
  events: RecentEvent[]
}

defineProps<Props>()
defineEmits<{
  (e: 'refresh'): void
}>()

const { t } = useI18n()
const { dateLocale } = useLocale()

function formatTime(iso: string | null): string {
  if (!iso) return t('dashboard.unknown')
  return new Date(iso).toLocaleString(dateLocale.value)
}

function statusType(status: string): string {
  const map: Record<string, string> = {
    open: 'danger',
    acknowledged: 'warning',
    resolved: 'success',
    closed: 'info',
  }
  return map[status] || 'info'
}

function severityType(severity: string): string {
  const map: Record<string, string> = {
    critical: 'danger',
    warning: 'warning',
    info: 'info',
  }
  return map[severity] || 'info'
}
</script>
