import apiClient from './client'

export interface RecentOfflineNode {
  node_id: string
  name: string
  status: string
  last_seen: string | null
}

export interface NodeStatus {
  total: number
  online: number
  offline: number
  recent_offline: RecentOfflineNode[]
}

export interface AlertStats {
  firing: number
  critical: number
  warning: number
  info: number
  today_new: number
}

export interface RecentEvent {
  id: number
  type: string
  title: string
  status: string
  severity: string
  timestamp: string | null
}

export interface DashboardSummary {
  node_status: NodeStatus
  alert_stats: AlertStats
  recent_events: RecentEvent[]
}

export async function getDashboardSummary(): Promise<DashboardSummary> {
  const response = await apiClient.get<DashboardSummary>('/v1/dashboard/summary')
  return response.data
}

export async function getRecentEvents(limit = 10): Promise<{ events: RecentEvent[] }> {
  const response = await apiClient.get<{ events: RecentEvent[] }>('/v1/dashboard/recent-events', {
    params: { limit },
  })
  return response.data
}

export async function getAlertStats(): Promise<AlertStats> {
  const response = await apiClient.get<AlertStats>('/v1/dashboard/alert-stats')
  return response.data
}
