<template>
  <div class="dashboard-home">
    <h2>{{ t('dashboard.title') }}</h2>

    <el-alert
      v-if="errorMessage"
      :title="errorMessage"
      type="error"
      show-icon
      closable
      @close="errorMessage = ''"
      style="margin-bottom: 16px"
    />

    <el-row :gutter="20">
      <el-col :xs="24" :md="12">
        <node-status-card :node-status="summary?.node_status || null" />
      </el-col>
      <el-col :xs="24" :md="12">
        <alert-stats-card :alert-stats="summary?.alert_stats || null" />
      </el-col>
    </el-row>

    <el-row :gutter="20" style="margin-top: 8px">
      <el-col :span="24">
        <recent-events-card :events="summary?.recent_events || []" @refresh="loadSummary" />
      </el-col>
    </el-row>

    <el-row :gutter="20" style="margin-top: 8px">
      <el-col :span="24">
        <el-card shadow="hover">
          <template #header>
            <div class="card-header">
              <span>{{ t('dashboard.realtime.title') }}</span>
              <el-tag :type="realtimeStore.connected ? 'success' : 'info'" size="small">
                {{ realtimeStore.connected ? t('dashboard.realtime.connected') : t('dashboard.realtime.disconnected') }}
              </el-tag>
            </div>
          </template>
          <div v-if="realtimeStore.latestAlert" class="realtime-item">
            <strong>{{ t('dashboard.realtime.latestAlert') }}</strong>
            {{ realtimeStore.latestAlert.payload.rule_name || realtimeStore.latestAlert.event_type }}
          </div>
          <div v-if="realtimeStore.latestIncident" class="realtime-item">
            <strong>{{ t('dashboard.realtime.latestIncident') }}</strong>
            {{ realtimeStore.latestIncident.payload.title || realtimeStore.latestIncident.event_type }}
          </div>
          <div v-if="!realtimeStore.latestAlert && !realtimeStore.latestIncident" class="empty-placeholder">
            {{ t('dashboard.realtime.empty') }}
          </div>
        </el-card>
      </el-col>
    </el-row>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useI18n } from 'vue-i18n'
import { getDashboardSummary, type DashboardSummary } from '@/api/dashboard'
import { useRealtimeStore } from '@/stores/realtime'
import { useRealtime } from '@/composables/useRealtime'
import NodeStatusCard from '@/components/dashboard/NodeStatusCard.vue'
import AlertStatsCard from '@/components/dashboard/AlertStatsCard.vue'
import RecentEventsCard from '@/components/dashboard/RecentEventsCard.vue'

const { t } = useI18n()
const summary = ref<DashboardSummary | null>(null)
const loading = ref(false)
const errorMessage = ref('')

const realtimeStore = useRealtimeStore()
useRealtime(['alerts', 'incidents', 'nodes'])

async function loadSummary() {
  loading.value = true
  errorMessage.value = ''
  try {
    summary.value = await getDashboardSummary()
  } catch (error: any) {
    const msg = error.response?.data?.detail || t('dashboard.loadFailed')
    errorMessage.value = msg
    ElMessage.error(msg)
  } finally {
    loading.value = false
  }
}

onMounted(() => {
  loadSummary()
})
</script>

<style scoped>
.dashboard-home h2 {
  margin-top: 0;
  margin-bottom: 20px;
}

.realtime-item {
  padding: 8px 0;
  border-bottom: 1px solid var(--el-border-color-lighter);
}

.realtime-item:last-child {
  border-bottom: none;
}
</style>
