<template>
  <el-card class="dashboard-card" shadow="hover">
    <template #header>
      <div class="card-header">
        <span>{{ t('dashboard.nodeStatus.title') }}</span>
        <el-tag v-if="nodeStatus" :type="nodeStatus.offline > 0 ? 'danger' : 'success'">
          {{ t('dashboard.nodeStatus.onlineTag', { online: nodeStatus.online, total: nodeStatus.total }) }}
        </el-tag>
      </div>
    </template>

    <div v-if="nodeStatus" class="node-stats">
      <div class="stat-row">
        <div class="stat-item">
          <div class="stat-value text-success">{{ nodeStatus.online }}</div>
          <div class="stat-label">{{ t('dashboard.nodeStatus.online') }}</div>
        </div>
        <div class="stat-item">
          <div class="stat-value" :class="nodeStatus.offline > 0 ? 'text-danger' : ''">
            {{ nodeStatus.offline }}
          </div>
          <div class="stat-label">{{ t('dashboard.nodeStatus.offline') }}</div>
        </div>
      </div>

      <el-divider />

      <div class="recent-offline">
        <div class="section-title">{{ t('dashboard.nodeStatus.recentOffline') }}</div>
        <el-table :data="nodeStatus.recent_offline" size="small" v-if="nodeStatus.recent_offline.length">
          <el-table-column prop="name" :label="t('dashboard.nodeStatus.nodeColumn')" />
          <el-table-column prop="last_seen" :label="t('dashboard.nodeStatus.lastSeen')">
            <template #default="{ row }">
              {{ formatTime(row.last_seen) }}
            </template>
          </el-table-column>
        </el-table>
        <div v-else class="empty-placeholder">{{ t('dashboard.nodeStatus.emptyOffline') }}</div>
      </div>
    </div>

    <el-skeleton v-else :rows="4" animated />
  </el-card>
</template>

<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import { useLocale } from '@/composables/useLocale'
import type { NodeStatus } from '@/api/dashboard'

interface Props {
  nodeStatus: NodeStatus | null
}

defineProps<Props>()

const { t } = useI18n()
const { dateLocale } = useLocale()

function formatTime(iso: string | null): string {
  if (!iso) return t('dashboard.unknown')
  return new Date(iso).toLocaleString(dateLocale.value)
}
</script>

<style scoped>
.node-stats {
  padding: 8px 0;
}

.stat-row {
  display: flex;
  gap: 32px;
  margin-bottom: 16px;
}

.stat-item {
  flex: 1;
}

.section-title {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 12px;
}

.text-success {
  color: var(--el-color-success);
}

.text-danger {
  color: var(--el-color-danger);
}
</style>
